import React, { useEffect, useState } from 'react';
import 'bootstrap/dist/css/bootstrap.min.css';
import { getAllMovies, changeMovieStatus, createMovie } from '../api/movieApi';

import MovieSearch from './MovieSearch';

const MovieList = () => {
    const [movies, setMovies] = useState([]);
    const [showSearch, setShowSearch] = useState(false);
    const [newMovieName, setNewMovieName] = useState("");
    const [newMovieDescription, setNewMovieDescription] = useState("");
    const [message, setMessage] = useState("");

    const fetchMovies = async () => {
        try {
            const res = await getAllMovies();
            setMovies(res.data);
        } catch (error) {
            console.error("Error al cargar las películas:", error);
        }
    };

    const handleCreateMovie = async () => {
        if (!newMovieName) {
            setMessage("Debe ingresar un nombre de película");
            return;
        }

        try {
            const res = await createMovie(newMovieName, newMovieDescription);
            setMovies([...movies, res.data]);
            setMessage(`Película "${res.data.name}" creada correctamente`);
            setNewMovieName("");
            setNewMovieDescription("");
        } catch (error) {
            setMessage(error.response?.data?.message || "Error al crear la película");
        }
    };

    const handleChangeStatus = async (id, newStatus) => {
        try {
            await changeMovieStatus(id, newStatus);
            setMovies(movies.map(m => m.id === id ? { ...m, status: newStatus } : m));
        } catch (error) {
            console.error("Error al cambiar el estado:", error);
            alert("No se pudo cambiar el estado");
        }
    };

    useEffect(() => {
        if (!showSearch) fetchMovies();
    }, [showSearch]);

    return (
        <div className="container mt-4">
            <nav className="navbar navbar-expand-lg navbar-light bg-light rounded mb-4 shadow">
                <div className="container-fluid">
                    <div className="container-fluid">
                        <img src="https://getbootstrap.com/docs/5.3/assets/brand/bootstrap-logo.svg" alt="Logo" width="30" height="24" className="d-inline-block align-text-top" />
                        <a className="navbar-brand">Peliculas Frontend - React</a>
                    </div>
                    <button className="navbar-toggler" type="button" data-bs-toggle="collapse" data-bs-target="#navbarNav"
                        aria-controls="navbarNav" aria-expanded="false" aria-label="Toggle navigation">
                        <span className="navbar-toggler-icon"></span>
                    </button>
                    <div className="collapse navbar-collapse" id="navbarNav">
                        <ul className="navbar-nav ms-auto d-flex align-items-center">
                            <li className="nav-item">
                                <button
                                    className="btn btn-primary btn-sm"
                                    onClick={() => setShowSearch(true)}
                                >
                                    Buscar Película
                                </button>
                            </li>

                            <li className="nav-item ms-2">
                                <button
                                    className="btn btn-success btn-sm"
                                    onClick={() => setShowSearch(false)}
                                >
                                    Lista de Películas
                                </button>
                            </li>
                        </ul>
                    </div>

                </div>
            </nav>

            <div className="mb-3">
    <input
        type="text"
        className="form-control mb-2"
        placeholder="Nombre de la nueva película"
        value={newMovieName}
        onChange={(e) => setNewMovieName(e.target.value)}
    />
    <input
        type="text"
        className="form-control mb-2"
        placeholder="Descripción de la película (opcional)"
        value={newMovieDescription}
        onChange={(e) => setNewMovieDescription(e.target.value)}
    />
    <button className="btn btn-success mt-1" onClick={handleCreateMovie}>
        Crear Película
    </button>
    {message && <p className="mt-2 text-info">{message}</p>}
</div>



            {showSearch ? (
                <MovieSearch />
            ) : (
                <div className="table-responsive shadow rounded">
                    <table className="table table-striped table-hover table-bordered align-middle">
                        <thead className="table-dark">
                            <tr>
                                <th>Pelicula</th>
                                <th>Descripción</th>
                                <th>Estado</th>
                                <th>Acciones</th>
                            </tr>
                        </thead>
                        <tbody>
                            {movies.length > 0 ? (
                                movies.map((movie) => (
                                    <tr key={movie.id}>
                                        <td>{movie.name}</td>
                                        <td>{movie.description}</td>
                                        <td>
                                            <span className={`badge ${movie.status === 'A' ? 'bg-success' : 'bg-danger'}`}>
                                                {movie.status === 'A' ? 'Activo' : 'Inactivo'}
                                            </span>
                                        </td>
                                        <td>
                                            <button
                                                className="btn btn-sm btn-outline-primary ms-2"
                                                onClick={() => handleChangeStatus(movie.id, movie.status === 'A' ? 'I' : 'A')}
                                            >
                                                Cambiar Estado
                                            </button>
                                        </td>
                                    </tr>
                                ))
                            ) : (
                                <tr>
                                    <td colSpan="3" className="text-center">
                                        No hay películas disponibles
                                    </td>
                                </tr>
                            )}
                        </tbody>
                    </table>
                </div>
            )}
        </div>
    );
};

export default MovieList;
